verifier_source:
# Standalone, no imports, no I/O, deterministic, exact integer arithmetic, fail-closed.
# Entry point: verify(witness) — raises on any failed check, returns True on success.
# witness: a list of [p, k] pairs; p must be the Fermat prime 2^(2^k)+1.

def _is_prime(n):
    if n < 2:
        return False
    i = 2
    while i * i <= n:
        if n % i == 0:
            return False
        i = i + 1
    return True

def _is_pow2(n):
    return n > 0 and (n & (n - 1)) == 0

def _fermat_exponent(p):
    m = p - 1
    if not _is_pow2(m):
        return -1
    k = 0
    while m > 1:
        if m % 2 != 0:
            return -1
        m = m // 2
        k = k + 1
    if not _is_pow2(k):
        return -1
    if (2 ** k) + 1 != p:
        return -1
    return k

def _euler_minus_one(n, p):
    r = pow(n, (p - 1) // 2, p)
    if r == p - 1:
        return True
    if r == 1:
        return False
    raise AssertionError('unresolved Euler sign')

def _is_primitive_root(g, p):
    if g % p == 0:
        return False
    n = p - 1
    factors = []
    m = n
    d = 2
    while d * d <= m:
        if m % d == 0:
            factors.append(d)
            while m % d == 0:
                m = m // d
        d = d + 1
    if m > 1:
        factors.append(m)
    for f in factors:
        if pow(g, n // f, p) == 1:
            return False
    return pow(g, n, p) == 1

def verify(witness):
    if not isinstance(witness, list):
        raise AssertionError('witness must be a list')
    if len(witness) != 4:
        raise AssertionError('expected 4 entries')
    prev = 0
    for entry in witness:
        if not isinstance(entry, list) or len(entry) != 2:
            raise AssertionError('bad entry')
        p = entry[0]
        k = entry[1]
        if not isinstance(p, int) or not isinstance(k, int) or p < 5:
            raise AssertionError('bad p/k')
        if p <= prev:
            raise AssertionError('not strictly increasing')
        prev = p
        if not _is_prime(p):
            raise AssertionError('not prime: %d' % p)
        if _fermat_exponent(p) != k:
            raise AssertionError('not Fermat: %d' % p)
        if p % 3 != 2:
            raise AssertionError('not 2 mod 3: %d' % p)
        if p % 4 != 1:
            raise AssertionError('not 1 mod 4: %d' % p)
        if not _euler_minus_one(3, p):
            raise AssertionError('euler != -1: %d' % p)
        if not _is_primitive_root(3, p):
            raise AssertionError('not primitive root: %d' % p)
    if witness != [[5, 1], [17, 2], [257, 3], [65537, 4]]:
        raise AssertionError('unexpected prime set')
    return True
